// -----------------------------------------------------------------------------
// BenchmarkMetrics.h
//
// Header-only utility that bridges IpplTimings measurements to bencher.dev's
// Benchmark Metric Format (BMF). It filters emitted timers against a compile-time
// whitelist generated by add_ippl_benchmark() and writes one JSON file per
// benchmark invocation.
// -----------------------------------------------------------------------------

#ifndef IPPL_BENCHMARK_METRICS_H
#define IPPL_BENCHMARK_METRICS_H

#include <algorithm>
#include <array>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <numeric>
#include <string>
#include <string_view>
#include <vector>

#include "Utility/IpplTimings.h"

namespace ippl {
    namespace benchmark {

        namespace detail {
            template <std::size_t N>
            bool isWhitelisted(const std::string& name,
                               const std::array<std::string_view, N>& whitelist) {
                if constexpr (N == 0) {
                    return true;
                }
                return std::find(whitelist.begin(), whitelist.end(), name) != whitelist.end();
            }

            inline double computeMean(const std::vector<double>& values) {
                if (values.empty()) {
                    return 0.0;
                }
                return std::accumulate(values.begin(), values.end(), 0.0) / values.size();
            }

            inline double computeMin(const std::vector<double>& values) {
                if (values.empty()) {
                    return 0.0;
                }
                return *std::min_element(values.begin(), values.end());
            }

            inline double computeMax(const std::vector<double>& values) {
                if (values.empty()) {
                    return 0.0;
                }
                return *std::max_element(values.begin(), values.end());
            }
        }  // namespace detail

        /**
         * Write a BMF JSON file containing per-timer latency statistics.
         *
         * @param filename   Path to the output JSON file (written by rank 0 only).
         * @param whitelist  Compile-time array of timer names to emit. An empty array
         *                   means all timers are emitted.
         */
        template <std::size_t N>
        void writeBMF(const std::string& filename,
                      const std::array<std::string_view, N>& whitelist) {
            if (ippl::Comm->rank() != 0) {
                return;
            }

            std::vector<std::string> timerNames = IpplTimings::getTimerNames();

            std::ostringstream json;
            json << std::setprecision(17) << std::scientific;
            json << "{\n";

            bool first = true;
            for (const auto& name : timerNames) {
                if (!detail::isWhitelisted(name, whitelist)) {
                    continue;
                }

                IpplTimings::TimerRef ref  = IpplTimings::getTimer(name.c_str());
                std::vector<double> values = IpplTimings::getMeasurements(ref);
                std::size_t count          = values.size();

                if (count == 0) {
                    continue;
                }

                // IpplTimings stores values in seconds. Bencher's latency measure
                // uses nanoseconds, so scale before emitting.
                constexpr double seconds_to_nanoseconds = 1.0e9;
                double mean = detail::computeMean(values) * seconds_to_nanoseconds;
                double minv = detail::computeMin(values) * seconds_to_nanoseconds;
                double maxv = detail::computeMax(values) * seconds_to_nanoseconds;

                if (!first) {
                    json << ",\n";
                }
                first = false;

                json << "  \"" << name << "\": {\n";
                json << "    \"latency\": {\n";
                json << "      \"value\": " << mean << ",\n";
                json << "      \"lower_value\": " << minv << ",\n";
                json << "      \"upper_value\": " << maxv << "\n";
                json << "    },\n";
                json << "    \"count\": {\n";
                json << "      \"value\": " << count << "\n";
                json << "    }\n";
                json << "  }";
            }

            json << "\n}\n";

            std::ofstream out(filename);
            out << json.str();
        }

    }  // namespace benchmark
}  // namespace ippl

#endif
